-- Schema for case_01_museum
DROP DATABASE IF EXISTS case_01_museum;
CREATE DATABASE case_01_museum CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE case_01_museum;

CREATE TABLE IF NOT EXISTS visitors (
  id INT NOT NULL AUTO_INCREMENT,
  full_name VARCHAR(100) NOT NULL,
  badge_zone VARCHAR(10) NOT NULL COMMENT 'PUBLIC, VIP, STAFF',
  entry_at DATETIME NOT NULL,
  exit_at DATETIME NULL,
  PRIMARY KEY (id),
  INDEX idx_badge_zone (badge_zone),
  INDEX idx_exit_at (exit_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS security_events (
  id INT NOT NULL AUTO_INCREMENT,
  visitor_id INT NOT NULL,
  zone VARCHAR(20) NOT NULL COMMENT 'LOBBY, GALLERY_A, GALLERY_B, STORAGE',
  event_type VARCHAR(30) NOT NULL COMMENT 'ZONE_ENTERED, DOOR_OPENED, ALARM_TRIGGERED',
  event_at DATETIME NOT NULL,
  PRIMARY KEY (id),
  INDEX idx_visitor_id (visitor_id),
  CONSTRAINT fk_se_visitor FOREIGN KEY (visitor_id) REFERENCES visitors (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

