  CONSTRAINT fk_do_bartender FOREIGN KEY (bartender_id) REFERENCES bartenders (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

