-- Schema for case_04_drug_empire
DROP DATABASE IF EXISTS case_04_drug_empire;
CREATE DATABASE case_04_drug_empire CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE case_04_drug_empire;

CREATE TABLE IF NOT EXISTS owners (
  id INT NOT NULL AUTO_INCREMENT,
  full_name VARCHAR(100) NOT NULL,
  phone VARCHAR(20) NOT NULL,
  has_criminal_record TINYINT(1) NOT NULL DEFAULT 0,
  registered_since DATE NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS stores (
  id INT NOT NULL AUTO_INCREMENT,
  store_name VARCHAR(100) NOT NULL,
  district VARCHAR(50) NOT NULL,
  owner_id INT NOT NULL,
  opened_date DATE NOT NULL,
  PRIMARY KEY (id),
  INDEX idx_owner_id (owner_id),
  CONSTRAINT fk_st_owner FOREIGN KEY (owner_id) REFERENCES owners (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS daily_revenue (
  id INT NOT NULL AUTO_INCREMENT,
  store_id INT NOT NULL,
  report_date DATE NOT NULL,
  declared_revenue DECIMAL(12,2) NOT NULL,
  actual_inventory_value DECIMAL(12,2) NOT NULL,
  PRIMARY KEY (id),
  INDEX idx_store_date (store_id, report_date),
  CONSTRAINT fk_dr_store FOREIGN KEY (store_id) REFERENCES stores (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

