-- ======================================================================
-- CASE 5: case_05_bank_insider
-- ======================================================================

-- Schema for case_05_bank_insider
DROP DATABASE IF EXISTS case_05_bank_insider;
CREATE DATABASE case_05_bank_insider CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE case_05_bank_insider;

CREATE TABLE IF NOT EXISTS employees (
  id INT NOT NULL AUTO_INCREMENT,
  full_name VARCHAR(100) NOT NULL,
  department VARCHAR(50) NOT NULL,
  access_level TINYINT NOT NULL COMMENT '1=teller, 2=supervisor, 3=manager',
  hire_date DATE NOT NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS accounts (
  account_number VARCHAR(20) NOT NULL,
  owner_name VARCHAR(100) NOT NULL,
  balance DECIMAL(15,2) NOT NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (account_number)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS transactions (
  id INT NOT NULL AUTO_INCREMENT,
  initiated_by INT NOT NULL,
  approved_by INT NULL COMMENT 'NULL or same as initiated_by = self-approved',
  account_number VARCHAR(20) NOT NULL,
  amount DECIMAL(15,2) NOT NULL,
  transaction_type VARCHAR(15) NOT NULL COMMENT 'WITHDRAWAL, TRANSFER, DEPOSIT',
  executed_at DATETIME NOT NULL,
  PRIMARY KEY (id),
  INDEX idx_initiated_by (initiated_by),
  INDEX idx_approved_by (approved_by),
  INDEX idx_account (account_number),
  CONSTRAINT fk_tx_initiated FOREIGN KEY (initiated_by) REFERENCES employees (id),
  CONSTRAINT fk_tx_approved FOREIGN KEY (approved_by) REFERENCES employees (id),
  CONSTRAINT fk_tx_account FOREIGN KEY (account_number) REFERENCES accounts (account_number)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Seed data for case_05_bank_insider
USE case_05_bank_insider;




-- ======================================================================
-- CASE 6: case_06_serial_killer
-- ======================================================================

-- Schema for case_06_serial_killer
DROP DATABASE IF EXISTS case_06_serial_killer;
CREATE DATABASE case_06_serial_killer CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE case_06_serial_killer;

CREATE TABLE IF NOT EXISTS `persons` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `full_name` VARCHAR(100) NOT NULL,
  `phone` VARCHAR(20) NOT NULL,
  `age` INT NOT NULL,
  `is_suspect` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS `victims` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `person_id` INT NOT NULL COMMENT 'FK to persons.id — victims also exist in persons table',
  `full_name` VARCHAR(100) NOT NULL,
  `age` INT NOT NULL,
  `disappeared_at` DATETIME NOT NULL,
  `last_known_location` VARCHAR(100) NOT NULL,
  PRIMARY KEY (`id`),
  INDEX `idx_person_id` (`person_id`),
  CONSTRAINT `fk_v_person` FOREIGN KEY (`person_id`) REFERENCES `persons` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS `meetings` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `person_a_id` INT NOT NULL COMMENT 'person from persons table',
  `person_b_id` INT NOT NULL COMMENT 'victim person_id from persons table — victims also appear in persons',
  `meeting_at` DATETIME NOT NULL,
  `location` VARCHAR(100) NOT NULL,
  `platform` VARCHAR(20) NOT NULL COMMENT 'APP, PHONE, IN_PERSON',
  PRIMARY KEY (`id`),
  INDEX `idx_person_a` (`person_a_id`, `meeting_at`),
  INDEX `idx_person_b` (`person_b_id`, `meeting_at`),
  CONSTRAINT `fk_mt_person_a` FOREIGN KEY (`person_a_id`) REFERENCES `persons` (`id`),
  CONSTRAINT `fk_mt_person_b` FOREIGN KEY (`person_b_id`) REFERENCES `persons` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS `phone_logs` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `caller_id` INT NOT NULL,
  `receiver_id` INT NOT NULL,
  `call_at` DATETIME NOT NULL,
  `duration_seconds` INT NOT NULL,
  `tower_location` VARCHAR(100) NOT NULL,
  PRIMARY KEY (`id`),
  INDEX `idx_caller` (`caller_id`, `call_at`),
  CONSTRAINT `fk_pl_caller` FOREIGN KEY (`caller_id`) REFERENCES `persons` (`id`),
  CONSTRAINT `fk_pl_receiver` FOREIGN KEY (`receiver_id`) REFERENCES `persons` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

