-- Schema for case_07_crypto
DROP DATABASE IF EXISTS case_07_crypto;
CREATE DATABASE case_07_crypto CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE case_07_crypto;

CREATE TABLE IF NOT EXISTS `real_persons` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `full_name` VARCHAR(100) NOT NULL,
  `national_id` VARCHAR(20) NOT NULL,
  `country` VARCHAR(50) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS `wallets` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `wallet_address` VARCHAR(64) NOT NULL,
  `owner_id` INT NULL COMMENT 'NULL = anonymous wallet',
  `created_at` DATETIME NOT NULL,
  `is_flagged` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_wallet_address` (`wallet_address`),
  INDEX `idx_is_flagged` (`is_flagged`),
  CONSTRAINT `fk_w_owner` FOREIGN KEY (`owner_id`) REFERENCES `real_persons` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS `crypto_transfers` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `from_wallet_id` INT NOT NULL,
  `to_wallet_id` INT NOT NULL,
  `amount_usd` DECIMAL(15,2) NOT NULL,
  `transferred_at` DATETIME NOT NULL,
  `blockchain` VARCHAR(20) NOT NULL COMMENT 'BTC, ETH, TRON',
  PRIMARY KEY (`id`),
  INDEX `idx_from_wallet` (`from_wallet_id`),
  INDEX `idx_to_wallet` (`to_wallet_id`),
  CONSTRAINT `fk_ct_from` FOREIGN KEY (`from_wallet_id`) REFERENCES `wallets` (`id`),
  CONSTRAINT `fk_ct_to` FOREIGN KEY (`to_wallet_id`) REFERENCES `wallets` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

