-- Schema for case_08_election
DROP DATABASE IF EXISTS case_08_election;
CREATE DATABASE case_08_election CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE case_08_election;

CREATE TABLE IF NOT EXISTS candidates (
  id INT NOT NULL AUTO_INCREMENT,
  full_name VARCHAR(100) NOT NULL,
  party VARCHAR(50) NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS polling_stations (
  id INT NOT NULL AUTO_INCREMENT,
  station_name VARCHAR(100) NOT NULL,
  district VARCHAR(50) NOT NULL,
  max_capacity INT NOT NULL,
  operator_id INT NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS voter_attendance (
  id INT NOT NULL AUTO_INCREMENT,
  station_id INT NOT NULL,
  voter_hash VARCHAR(64) NOT NULL,
  checked_in_at DATETIME NOT NULL,
  PRIMARY KEY (id),
  INDEX idx_va_station (station_id),
  CONSTRAINT fk_va_station FOREIGN KEY (station_id) REFERENCES polling_stations (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS votes (
  id INT NOT NULL AUTO_INCREMENT,
  station_id INT NOT NULL,
  candidate_id INT NOT NULL,
  voter_hash VARCHAR(64) NOT NULL,
  voted_at DATETIME NOT NULL,
  PRIMARY KEY (id),
  INDEX idx_v_station_time (station_id, voted_at),
  CONSTRAINT fk_v_station FOREIGN KEY (station_id) REFERENCES polling_stations (id),
  CONSTRAINT fk_v_candidate FOREIGN KEY (candidate_id) REFERENCES candidates (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

