-- Schema for case_09_corporate_spy
DROP DATABASE IF EXISTS case_09_corporate_spy;
CREATE DATABASE case_09_corporate_spy CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE case_09_corporate_spy;

CREATE TABLE IF NOT EXISTS employees (
  id INT NOT NULL AUTO_INCREMENT,
  full_name VARCHAR(100) NOT NULL,
  department VARCHAR(50) NOT NULL,
  manager_id INT NULL COMMENT 'Self-referencing FK',
  clearance_level TINYINT NOT NULL COMMENT '1=general, 2=internal, 3=secret, 4=top_secret',
  hire_date DATE NOT NULL,
  resigned_at DATE NULL,
  PRIMARY KEY (id),
  INDEX idx_manager (manager_id),
  CONSTRAINT fk_emp_manager FOREIGN KEY (manager_id) REFERENCES employees (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS file_access_logs (
  id INT NOT NULL AUTO_INCREMENT,
  employee_id INT NOT NULL,
  file_name VARCHAR(100) NOT NULL,
  classification VARCHAR(15) NOT NULL COMMENT 'PUBLIC, INTERNAL, SECRET, TOP_SECRET',
  action VARCHAR(10) NOT NULL COMMENT 'READ, DOWNLOAD, PRINT',
  accessed_at DATETIME NOT NULL,
  PRIMARY KEY (id),
  INDEX idx_fal_employee (employee_id),
  INDEX idx_classification (classification),
  CONSTRAINT fk_fal_employee FOREIGN KEY (employee_id) REFERENCES employees (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS network_logs (
  id INT NOT NULL AUTO_INCREMENT,
  employee_id INT NOT NULL,
  destination_ip VARCHAR(45) NOT NULL,
  data_transferred_mb DECIMAL(8,2) NOT NULL,
  connected_at DATETIME NOT NULL,
  is_vpn TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  INDEX idx_nl_employee (employee_id),
  CONSTRAINT fk_nl_employee FOREIGN KEY (employee_id) REFERENCES employees (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS anomaly_flags (
  id INT NOT NULL AUTO_INCREMENT,
  employee_id INT NOT NULL,
  flag_type VARCHAR(30) NOT NULL COMMENT 'LATE_NIGHT_ACCESS, BULK_DOWNLOAD, EXTERNAL_TRANSFER',
  severity VARCHAR(10) NOT NULL COMMENT 'LOW, MEDIUM, HIGH',
  flagged_at DATETIME NOT NULL,
  PRIMARY KEY (id),
  INDEX idx_af_employee (employee_id),
  CONSTRAINT fk_af_employee FOREIGN KEY (employee_id) REFERENCES employees (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

