-- ======================================================================

-- Schema for case_10_supply_chain
DROP DATABASE IF EXISTS case_10_supply_chain;
CREATE DATABASE case_10_supply_chain CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE case_10_supply_chain;

CREATE TABLE IF NOT EXISTS employees (
  id INT NOT NULL AUTO_INCREMENT,
  full_name VARCHAR(100) NOT NULL,
  role VARCHAR(50) NOT NULL,
  department VARCHAR(50) NOT NULL,
  has_system_access TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS suppliers (
  id INT NOT NULL AUTO_INCREMENT,
  company_name VARCHAR(100) NOT NULL,
  country VARCHAR(50) NOT NULL,
  reliability_score DECIMAL(3,2) NOT NULL,
  is_deleted TINYINT(1) NOT NULL DEFAULT 0,
  deleted_at DATETIME NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS orders (
  id INT NOT NULL AUTO_INCREMENT,
  supplier_id INT NOT NULL,
  product_name VARCHAR(100) NOT NULL,
  quantity INT NOT NULL,
  unit_price DECIMAL(12,2) NOT NULL,
  expected_delivery DATE NOT NULL,
  actual_delivery DATE NULL,
  status VARCHAR(15) NOT NULL COMMENT 'PENDING, SHIPPED, DELIVERED, CANCELLED',
  modified_by INT NULL,
  PRIMARY KEY (id),
  INDEX idx_o_supplier (supplier_id, status),
  INDEX idx_o_modified (modified_by, status),
  CONSTRAINT fk_o_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers (id),
  CONSTRAINT fk_o_modified FOREIGN KEY (modified_by) REFERENCES employees (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS delivery_history (
  id INT NOT NULL AUTO_INCREMENT,
  order_id INT NOT NULL,
  old_expected_date DATE NOT NULL,
  new_expected_date DATE NOT NULL,
  changed_by INT NOT NULL,
  changed_at DATETIME NOT NULL,
  PRIMARY KEY (id),
  INDEX idx_dh_order (order_id),
  INDEX idx_dh_changed_by (changed_by),
  CONSTRAINT fk_dh_order FOREIGN KEY (order_id) REFERENCES orders (id),
  CONSTRAINT fk_dh_changed_by FOREIGN KEY (changed_by) REFERENCES employees (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE IF NOT EXISTS audit_trail (
  id INT NOT NULL AUTO_INCREMENT,
  table_name VARCHAR(50) NOT NULL,
  record_id INT NOT NULL,
  action VARCHAR(10) NOT NULL COMMENT 'INSERT, UPDATE, DELETE',
  performed_by INT NOT NULL,
  performed_at DATETIME NOT NULL,
  changed_field VARCHAR(50) NULL,
  old_value VARCHAR(255) NULL,
  new_value VARCHAR(255) NULL,
  PRIMARY KEY (id),
  INDEX idx_at_performed_by (performed_by),
  INDEX idx_at_performed_at (performed_at),
  CONSTRAINT fk_at_performed FOREIGN KEY (performed_by) REFERENCES employees (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

