INSERT IGNORE INTO premium_cases (id, title, description, difficulty, hint, db_path, order_index, question_count) VALUES
(1, 'The Museum Heist', 'A priceless painting disappeared from Gallery A during the opening night.', 'EASY', 'Check visitors and security events.', 'case_01_museum', 1, 1),
(2, 'The Social Media Stalker', 'Trace threatening messages back to their origin IP addresses.', 'MEDIUM', 'Analyze messages, accounts, and login logs.', 'case_02_social_killer', 2, 1),
(3, 'The Neon Club Murder', 'A murder inside the VIP Room at Neon Club.', 'MEDIUM', 'Cross-reference entry logs and drink orders.', 'case_03_neon_club', 3, 2),
(4, 'The Drug Syndicate', 'Uncover money laundering through retail stores declaring high revenues.', 'HARD', 'Compare declared revenue with inventory values.', 'case_04_drug_empire', 4, 2),
(5, 'The Bank Embezzlement', 'Salami slicing scheme with unauthorized self-approved withdrawals.', 'HARD', 'Find self-approved withdrawal transactions.', 'case_05_bank_insider', 5, 2),
(6, 'The Serial Killer', 'Track down a serial killer targeting multiple victims.', 'EXPERT', 'Analyze meetings and cellular BTS logs.', 'case_06_serial_killer', 6, 3),
(7, 'The Crypto Mixer', 'Trace ransomware funds laundered across mixer wallets using recursive CTE.', 'EXPERT', 'Use recursive CTE to trace wallet hops.', 'case_07_crypto', 7, 3),
(8, 'The Rigged Election', 'Detect fraudulent ballot stuffing and automated script voting.', 'HARD', 'Compare vote counts against voter attendance.', 'case_08_election', 8, 3),
(9, 'The Corporate Spy', 'Uncover unauthorized data exfiltration by insiders.', 'HARD', 'Identify clearance violations and burst downloads.', 'case_09_corporate_spy', 9, 3),
(10, 'The Supply Chain Sabotage', 'Sabotage targeting purchase orders and vendor master lists.', 'EXPERT', 'Investigate delivery delays and audit trails.', 'case_10_supply_chain', 10, 4);
